const rows = $input.all().map((i) => i.json);
const reminders = [];

for (const row of rows) {
  const employeeName = `${row.first_name} ${row.last_name}`;

  if (row.immediate_head_email) {
    reminders.push({
      to: row.immediate_head_email,
      recipient_type: 'immediate_head',
      employee_id: row.employee_id,
      employee_name: employeeName,
      position: row.position,
      probation_end_date: row.probation_end_date
    });
  }

  reminders.push({
    to: $env.HR_NOTIFICATION_EMAIL || 'hr@snconnect.local',
    recipient_type: 'hr',
    employee_id: row.employee_id,
    employee_name: employeeName,
    position: row.position,
    probation_end_date: row.probation_end_date
  });
}

return reminders.map((reminder) => ({ json: reminder }));
